   137→bool UWjWorldCurrencySubsystem::PurchaseItemWithCurrency(FName CosmeticItemId, ECurrencyType CurrencyType)
   138→{
   139→	if (bExchangePending)
   140→	{
   141→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   142→		return false;
   143→	}
   144→
   145→	if (CosmeticItemId.IsNone())
   146→	{
   147→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 CosmeticItemId"));
   148→		return false;
   149→	}
   150→
   151→	// 카탈로그에서 아이템 정보 조회
   152→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   153→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   154→	{
   155→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("CosmeticSubsystem 또는 카탈로그 없음"));
   156→		return false;
   157→	}
   158→
   159→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(CosmeticItemId);
   160→	if (!ItemDef)
   161→	{
   162→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 아이템 '%s' 찾을 수 없음"), *CosmeticItemId.ToString());
   163→		return false;
   164→	}
   165→
   166→	// 가격 확인
   167→	int32 ItemPrice = (CurrencyType == ECurrencyType::Coin) ? ItemDef->CoinPrice : ItemDef->GemPrice;
   168→	if (ItemPrice <= 0)
   169→	{
   170→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("아이템 '%s'은 %s로 구매할 수 없습니다 (가격: %d)"),
   171→			*CosmeticItemId.ToString(),
   172→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   173→			ItemPrice);
   174→		return false;
   175→	}
   176→
   177→	// 잔액 확인
   178→	int32 CurrentBalance = GetBalance(CurrencyType);
   179→	if (CurrentBalance < ItemPrice)
   180→	{
   181→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("잔액 부족: %s %d < %d"),
   182→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   183→			CurrentBalance, ItemPrice);
   184→		return false;
   185→	}
   186→
   187→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   188→	if (!Settings)
   189→	{
   190→		return false;
   191→	}
   192→
   193→	int32 CurrencyDefId = (CurrencyType == ECurrencyType::Coin) ? Settings->CoinSteamItemDefId : Settings->GemSteamItemDefId;
   194→	int32 CosmeticDefId = ItemDef->SteamItemDefId;
   195→
   196→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 구매 요청: %s (%d %s → CosmeticDefId %d)"),
   197→		*CosmeticItemId.ToString(), ItemPrice,
   198→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   199→		CosmeticDefId);
   200→
   201→#if WITH_STEAM
   202→	ISteamInventory* SteamInv = SteamInventory();
   203→	if (SteamInv && CosmeticDefId > 0)
   204→	{
   205→		// 캐시된 재화 인스턴스 ID 조회
   206→		SteamItemInstanceID_t CurrencyInstanceId = (CurrencyType == ECurrencyType::Coin)
   207→			? CachedCoinInstanceId
   208→			: CachedGemInstanceId;
   209→
   210→		if (CurrencyInstanceId == k_SteamItemInstanceIDInvalid)
   211→		{
   212→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("재화 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   213→			return false;
   214→		}
   215→
   216→		// 기존 핸들 정리
   217→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   218→		{
   219→			SteamInv->DestroyResult(ExchangeResultHandle);
   220→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   221→		}
   222→
   223→		// ExchangeItems: 재화 소비 → 코스메틱 아이템 획득
   224→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(CosmeticDefId);
   225→		uint32 OutputQuantity = 1;
   226→
   227→		uint32 InputQuantity = static_cast<uint32>(ItemPrice);
   228→
   229→		bool bExchangeResult = SteamInv->ExchangeItems(
   230→			&ExchangeResultHandle,
   231→			&OutputItemDef, &OutputQuantity, 1,       // 출력: 코스메틱 아이템 1개
   232→			&CurrencyInstanceId, &InputQuantity, 1     // 입력: 재화 인스턴스 × 가격
   233→		);
   234→
   235→		if (bExchangeResult)
   236→		{
   237→			bExchangePending = true;
   238→			bPendingIsPlacement = false;
   239→			PendingExchangeItemId = CosmeticItemId;
   240→			StartExchangePolling();
   241→
   242→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems 요청 성공: %s (CurrencyInstanceId=%llu, Price=%d)"),
   243→				*CosmeticItemId.ToString(), CurrencyInstanceId, ItemPrice);
   244→			return true;
   245→		}
   246→		else
   247→		{
   248→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam ExchangeItems 호출 실패: %s"), *CosmeticItemId.ToString());
   249→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   250→			return false;
   251→		}
   252→	}
   253→#endif
   254→
   255→	// 비Steam 폴백: 로컬 잔액 차감 + 아이템 부여
   256→	SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   257→	CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   258→
   259→	OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   260→
   261→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 구매 완료: %s (%d %s 차감)"),
   262→		*CosmeticItemId.ToString(), ItemPrice,
   263→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"));
   264→
   265→	return true;
   266→}
