   268→bool UWjWorldCurrencySubsystem::PurchasePlacementObject(FName ObjectId)
   269→{
   270→	if (bExchangePending)
   271→	{
   272→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   273→		return false;
   274→	}
   275→
   276→	if (ObjectId.IsNone())
   277→	{
   278→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 ObjectId"));
   279→		return false;
   280→	}
   281→
   282→	// DeveloperSettings에서 LobbyPlaceableCatalog 로드
   283→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   284→	if (!Settings)
   285→	{
   286→		return false;
   287→	}
   288→
   289→	UWjWorldPlaceableObjectDataAsset* PlacementCatalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::Lobby);
   290→	if (!PlacementCatalog)
   291→	{
   292→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("LobbyPlaceableCatalog 없음"));
   293→		return false;
   294→	}
   295→
   296→	const FPlaceableObjectDefinition* Def = PlacementCatalog->FindByObjectId(ObjectId);
   297→	if (!Def)
   298→	{
   299→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 오브젝트 '%s' 찾을 수 없음"), *ObjectId.ToString());
   300→		return false;
   301→	}
   302→
   303→	if (Def->CoinPrice <= 0)
   304→	{
   305→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("오브젝트 '%s'은 무료입니다 (구매 불필요)"), *ObjectId.ToString());
   306→		return false;
   307→	}
   308→
   309→	if (Def->SteamItemDefId <= 0)
   310→	{
   311→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("오브젝트 '%s'에 SteamItemDefId가 설정되지 않음"), *ObjectId.ToString());
   312→		return false;
   313→	}
   314→
   315→	// 잔액 확인
   316→	int32 CurrentBalance = GetBalance(ECurrencyType::Coin);
   317→	if (CurrentBalance < Def->CoinPrice)
   318→	{
   319→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Coin 잔액 부족: %d < %d"), CurrentBalance, Def->CoinPrice);
   320→		return false;
   321→	}
   322→
   323→	UE_LOG(LogWjWorldCurrency, Log, TEXT("배치 오브젝트 구매 요청: %s (%d Coin → DefId %d)"),
   324→		*ObjectId.ToString(), Def->CoinPrice, Def->SteamItemDefId);
   325→
   326→#if WITH_STEAM
   327→	ISteamInventory* SteamInv = SteamInventory();
   328→	if (SteamInv)
   329→	{
   330→		SteamItemInstanceID_t CoinInstanceId = CachedCoinInstanceId;
   331→		if (CoinInstanceId == k_SteamItemInstanceIDInvalid)
   332→		{
   333→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Coin 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   334→			return false;
   335→		}
   336→
   337→		// 기존 핸들 정리
   338→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   339→		{
   340→			SteamInv->DestroyResult(ExchangeResultHandle);
   341→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   342→		}
   343→
   344→		// ExchangeItems: Coin 소비 → 배치 오브젝트 아이템 획득
   345→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(Def->SteamItemDefId);
   346→		uint32 OutputQuantity = 1;
   347→		uint32 InputQuantity = static_cast<uint32>(Def->CoinPrice);
   348→
   349→		bool bExchangeResult = SteamInv->ExchangeItems(
   350→			&ExchangeResultHandle,
   351→			&OutputItemDef, &OutputQuantity, 1,
   352→			&CoinInstanceId, &InputQuantity, 1
   353→		);
   354→
   355→		if (bExchangeResult)
   356→		{
   357→			bExchangePending = true;
   358→			bPendingIsPlacement = true;
   359→			PendingExchangeItemId = ObjectId;
   360→			StartExchangePolling();
   361→
   362→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems 요청 성공 (배치): %s (CoinInstanceId=%llu, Price=%d)"),
   363→				*ObjectId.ToString(), CoinInstanceId, Def->CoinPrice);
   364→			return true;
   365→		}
   366→		else
   367→		{
   368→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam ExchangeItems 호출 실패 (배치): %s"), *ObjectId.ToString());
   369→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   370→			return false;
   371→		}
   372→	}
   373→#endif
   374→
   375→	// 비Steam 폴백: 로컬 잔액 차감 + 로컬 소유 수량 증가
   376→	SetBalance(ECurrencyType::Coin, CurrentBalance - Def->CoinPrice);
   377→
   378→	// GConfig에 소유 수량 기록
   379→	static const FString PlacementInventorySection = TEXT("PlacementInventory");
   380→	int32 CurrentOwned = 0;
   381→	GConfig->GetInt(*PlacementInventorySection, *ObjectId.ToString(), CurrentOwned, GGameUserSettingsIni);
   382→	GConfig->SetInt(*PlacementInventorySection, *ObjectId.ToString(), CurrentOwned + 1, GGameUserSettingsIni);
   383→	GConfig->Flush(false, GGameUserSettingsIni);
   384→
   385→	// CosmeticSubsystem의 AllItemQuantities도 갱신 (비Steam)
   386→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   387→	if (CosmeticSub)
   388→	{
   389→		CosmeticSub->AllItemQuantities.FindOrAdd(Def->SteamItemDefId) += 1;
   390→	}
   391→
   392→	OnPlacementPurchaseComplete.Broadcast(ObjectId, true);
   393→
   394→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 배치 오브젝트 구매 완료: %s (%d Coin 차감)"),
   395→		*ObjectId.ToString(), Def->CoinPrice);
   396→
   397→	return true;
   398→}
