   400→bool UWjWorldCurrencySubsystem::PurchaseGemPack(int32 PackDefId)
   401→{
   402→	if (bGemPurchasePending)
   403→	{
   404→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 Gem 팩 구매가 진행 중입니다."));
   405→		return false;
   406→	}
   407→
   408→#if WITH_STEAM
   409→	ISteamInventory* SteamInv = SteamInventory();
   410→	if (!SteamInv)
   411→	{
   412→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Inventory API 사용 불가"));
   413→		return false;
   414→	}
   415→
   416→	// 기존 핸들 정리
   417→	if (GemPurchaseResultHandle != k_SteamInventoryResultInvalid)
   418→	{
   419→		SteamInv->DestroyResult(GemPurchaseResultHandle);
   420→		GemPurchaseResultHandle = k_SteamInventoryResultInvalid;
   421→	}
   422→
   423→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(PackDefId);
   424→	uint32 Quantity = 1;
   425→
   426→	if (SteamInv->StartPurchase(&ItemDef, &Quantity, 1))
   427→	{
   428→		bGemPurchasePending = true;
   429→		StartGemPurchasePolling();
   430→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Gem 팩 구매 요청 시작 (DefId: %d)"), PackDefId);
   431→		return true;
   432→	}
   433→	else
   434→	{
   435→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam StartPurchase 실패 (DefId: %d)"), PackDefId);
   436→		return false;
   437→	}
   438→#else
   439→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매는 Steam 환경에서만 가능합니다."));
   440→	return false;
   441→#endif
   442→}
