   444→void UWjWorldCurrencySubsystem::RefreshBalancesFromInventory()
   445→{
   446→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   447→	if (!Settings)
   448→	{
   449→		return;
   450→	}
   451→
   452→#if WITH_STEAM
   453→	ISteamInventory* SteamInv = SteamInventory();
   454→	if (SteamInv)
   455→	{
   456→		// 단일 GetAllItems 호출로 잔액 + 인스턴스 ID 동시 캐싱
   457→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   458→		if (!SteamInv->GetAllItems(&ResultHandle))
   459→		{
   460→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam GetAllItems 실패"));
   461→			return;
   462→		}
   463→
   464→		int32 NewCoinBalance = 0;
   465→		int32 NewGemBalance = 0;
   466→		SteamItemInstanceID_t NewCoinInstanceId = k_SteamItemInstanceIDInvalid;
   467→		SteamItemInstanceID_t NewGemInstanceId = k_SteamItemInstanceIDInvalid;
   468→
   469→		EResult Status = SteamInv->GetResultStatus(ResultHandle);
   470→		if (Status == k_EResultOK)
   471→		{
   472→			uint32 ItemCount = 0;
   473→			if (SteamInv->GetResultItems(ResultHandle, nullptr, &ItemCount) && ItemCount > 0)
   474→			{
   475→				TArray<SteamItemDetails_t> ItemDetails;
   476→				ItemDetails.SetNum(ItemCount);
   477→
   478→				if (SteamInv->GetResultItems(ResultHandle, ItemDetails.GetData(), &ItemCount))
   479→				{
   480→					for (uint32 i = 0; i < ItemCount; ++i)
   481→					{
   482→						const SteamItemDetails_t& Detail = ItemDetails[i];
   483→						if (Detail.m_unQuantity == 0)
   484→						{
   485→							continue;
   486→						}
   487→
   488→						if (Detail.m_iDefinition == Settings->CoinSteamItemDefId)
   489→						{
   490→							NewCoinBalance += Detail.m_unQuantity;
   491→							NewCoinInstanceId = Detail.m_itemId;
   492→						}
   493→						else if (Detail.m_iDefinition == Settings->GemSteamItemDefId)
   494→						{
   495→							NewGemBalance += Detail.m_unQuantity;
   496→							NewGemInstanceId = Detail.m_itemId;
   497→						}
   498→					}
   499→				}
   500→			}
   501→		}
   502→
   503→		SteamInv->DestroyResult(ResultHandle);
   504→
   505→		// 인스턴스 ID 캐시 갱신
   506→		CachedCoinInstanceId = NewCoinInstanceId;
   507→		CachedGemInstanceId = NewGemInstanceId;
   508→
   509→		// 잔액 갱신
   510→		if (NewCoinBalance != CoinBalance)
   511→		{
   512→			SetBalance(ECurrencyType::Coin, NewCoinBalance);
   513→		}
   514→		if (NewGemBalance != GemBalance)
   515→		{
   516→			SetBalance(ECurrencyType::Gem, NewGemBalance);
   517→		}
   518→
   519→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam 잔액 갱신: Coin=%d (InstanceId=%llu), Gem=%d (InstanceId=%llu)"),
   520→			CoinBalance, CachedCoinInstanceId, GemBalance, CachedGemInstanceId);
   521→		return;
   522→	}
   523→#endif
   524→
   525→	// 비Steam: 로컬 값 유지
   526→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 잔액: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   527→}
