   578→			SteamInv->DestroyResult(ResultHandle);
   579→		}
   580→		else
   581→		{
   582→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Coin 소비 요청 실패"));
   583→		}
   584→	}
   585→
   586→	if (CachedGemInstanceId != k_SteamItemInstanceIDInvalid && GemBalance > 0)
   587→	{
   588→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   589→		if (SteamInv->ConsumeItem(&ResultHandle, CachedGemInstanceId, static_cast<uint32>(GemBalance)))
   590→		{
   591→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Gem 소비 요청 성공: %d개 (InstanceId=%llu)"), GemBalance, CachedGemInstanceId);
   592→			SteamInv->DestroyResult(ResultHandle);
   593→		}
   594→		else
   595→		{
   596→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Gem 소비 요청 실패"));
   597→		}
   598→	}
   599→
   600→	// 인벤토리 갱신으로 잔액 반영
   601→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   602→	if (CosmeticSub)
   603→	{
   604→		CosmeticSub->RequestInventoryRefresh();
   605→	}
   606→#else
   607→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamCurrency: Steam 환경에서만 사용 가능"));
   608→#endif
   609→}
