   611→void UWjWorldCurrencySubsystem::DebugConsumeAllSteamItems()
   612→{
   613→#if WITH_STEAM
   614→	ISteamInventory* SteamInv = SteamInventory();
   615→	if (!SteamInv)
   616→	{
   617→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam Inventory API 없음"));
   618→		return;
   619→	}
   620→
   621→	SteamInventoryResult_t AllItemsHandle = k_SteamInventoryResultInvalid;
   622→	if (!SteamInv->GetAllItems(&AllItemsHandle))
   623→	{
   624→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 실패"));
   625→		return;
   626→	}
   627→
   628→	EResult Status = SteamInv->GetResultStatus(AllItemsHandle);
   629→	if (Status != k_EResultOK)
   630→	{
   631→		SteamInv->DestroyResult(AllItemsHandle);
   632→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 상태 실패 (%d)"), static_cast<int32>(Status));
   633→		return;
   634→	}
   635→
   636→	uint32 ItemCount = 0;
   637→	if (!SteamInv->GetResultItems(AllItemsHandle, nullptr, &ItemCount) || ItemCount == 0)
   638→	{
   639→		SteamInv->DestroyResult(AllItemsHandle);
   640→		UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: 인벤토리가 이미 비어있음"));
   641→		return;
   642→	}
   643→
   644→	TArray<SteamItemDetails_t> Items;
   645→	Items.SetNum(ItemCount);
   646→	SteamInv->GetResultItems(AllItemsHandle, Items.GetData(), &ItemCount);
   647→	SteamInv->DestroyResult(AllItemsHandle);
   648→
   649→	int32 ConsumedCount = 0;
   650→	for (const SteamItemDetails_t& Detail : Items)
   651→	{
   652→		if (Detail.m_unQuantity == 0)
   653→		{
   654→			continue;
   655→		}
   656→
   657→		SteamInventoryResult_t ConsumeHandle = k_SteamInventoryResultInvalid;
   658→		if (SteamInv->ConsumeItem(&ConsumeHandle, Detail.m_itemId, Detail.m_unQuantity))
   659→		{
   660→			UE_LOG(LogWjWorldCurrency, Log, TEXT("  소비: DefId=%d, Quantity=%d, InstanceId=%llu"),
   661→				Detail.m_iDefinition, Detail.m_unQuantity, Detail.m_itemId);
   662→			SteamInv->DestroyResult(ConsumeHandle);
   663→			++ConsumedCount;
   664→		}
   665→	}
   666→
   667→	// 캐시 초기화
   668→	CachedCoinInstanceId = k_SteamItemInstanceIDInvalid;
   669→	CachedGemInstanceId = k_SteamItemInstanceIDInvalid;
   670→
   671→	// 인벤토리 갱신
   672→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   673→	if (CosmeticSub)
   674→	{
   675→		CosmeticSub->RequestInventoryRefresh();
   676→	}
   677→
   678→	UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: %d/%d 아이템 소비 완료"), ConsumedCount, ItemCount);
   679→#else
   680→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam 환경에서만 사용 가능"));
   681→#endif
   682→}
