   689→void UWjWorldCurrencySubsystem::PollExchangeResult()
   690→{
   691→#if WITH_STEAM
   692→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   693→	{
   694→		StopExchangePolling();
   695→		return;
   696→	}
   697→
   698→	ISteamInventory* SteamInv = SteamInventory();
   699→	if (!SteamInv)
   700→	{
   701→		StopExchangePolling();
   702→		bExchangePending = false;
   703→		if (bPendingIsPlacement)
   704→		{
   705→			OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   706→		}
   707→		else
   708→		{
   709→			OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   710→		}
   711→		bPendingIsPlacement = false;
   712→		PendingExchangeItemId = NAME_None;
   713→		return;
   714→	}
   715→
   716→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   717→	if (Status == k_EResultPending)
   718→	{
   719→		return;
   720→	}
   721→
   722→	bool bSuccess = (Status == k_EResultOK);
   723→	if (bSuccess)
   724→	{
   725→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   726→
   727→		// 인벤토리 갱신
   728→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   729→		if (CosmeticSub)
   730→		{
   731→			CosmeticSub->RequestInventoryRefresh();
   732→		}
   733→	}
   734→	else
   735→	{
   736→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   737→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   738→	}
   739→
   740→	SteamInv->DestroyResult(ExchangeResultHandle);
   741→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   742→
   743→	bExchangePending = false;
   744→
   745→	// 배치 vs 코스메틱 분기
   746→	if (bPendingIsPlacement)
   747→	{
   748→		OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   749→	}
   750→	else
   751→	{
   752→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   753→	}
   754→	bPendingIsPlacement = false;
   755→	PendingExchangeItemId = NAME_None;
   756→
   757→	StopExchangePolling();
   758→#else
   759→	StopExchangePolling();
   760→#endif
   761→}
   762→
   763→void UWjWorldCurrencySubsystem::StartExchangePolling()
   764→{
   765→	UWorld* World = GetWorld();
   766→	if (!World)
   767→	{
   768→		return;
   769→	}
   770→
   771→	World->GetTimerManager().SetTimer(
   772→		ExchangePollTimerHandle,
   773→		this,
   774→		&UWjWorldCurrencySubsystem::PollExchangeResult,
   775→		0.5f,
   776→		true
   777→	);
   778→}
   779→
   780→void UWjWorldCurrencySubsystem::StopExchangePolling()
   781→{
   782→	UWorld* World = GetWorld();
   783→	if (World)
   784→	{
   785→		World->GetTimerManager().ClearTimer(ExchangePollTimerHandle);
   786→	}
   787→}
   788→
   789→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   790→{
   791→#if WITH_STEAM
   792→	if (!bGemPurchasePending)
   793→	{
   794→		StopGemPurchasePolling();
   795→		return;
   796→	}
   797→
   798→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   799→	// 인벤토리 변경을 감지하여 완료 판단
   800→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   801→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   802→
   803→	// 간단한 타임아웃 처리 (300초)
   804→	UWorld* World = GetWorld();
   805→	if (World)
   806→	{
   807→		if (GemPurchaseStartTime == 0.0f)
   808→		{
   809→			GemPurchaseStartTime = World->GetTimeSeconds();
   810→		}
   811→
   812→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   813→		if (ElapsedTime > 300.0f)
   814→		{
   815→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   816→			bGemPurchasePending = false;
   817→			GemPurchaseStartTime = 0.0f;
   818→			StopGemPurchasePolling();
   819→		}
   820→	}
   821→#else
   822→	StopGemPurchasePolling();
   823→#endif
   824→}
   825→
   826→void UWjWorldCurrencySubsystem::StartGemPurchasePolling()
   827→{
   828→	UWorld* World = GetWorld();
   829→	if (!World)
   830→	{
   831→		return;
   832→	}
   833→
   834→	World->GetTimerManager().SetTimer(
   835→		GemPurchasePollTimerHandle,
   836→		this,
   837→		&UWjWorldCurrencySubsystem::PollGemPurchaseResult,
   838→		1.0f,
   839→		true
   840→	);
   841→}
   842→
   843→void UWjWorldCurrencySubsystem::StopGemPurchasePolling()
   844→{
   845→	UWorld* World = GetWorld();
   846→	if (World)
   847→	{
   848→		World->GetTimerManager().ClearTimer(GemPurchasePollTimerHandle);
   849→	}
   850→}
