   852→void UWjWorldCurrencySubsystem::SaveBalancesToLocal()
   853→{
   854→	GConfig->SetInt(*CurrencyConfigSection, TEXT("CoinBalance"), CoinBalance, GGameUserSettingsIni);
   855→	GConfig->SetInt(*CurrencyConfigSection, TEXT("GemBalance"), GemBalance, GGameUserSettingsIni);
   856→
   857→	GConfig->Flush(false, GGameUserSettingsIni);
   858→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 저장 완료"));
   859→}
