   861→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   862→{
   863→	int32 LoadedCoin = 0;
   864→	int32 LoadedGem = 0;
   865→
   866→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, GGameUserSettingsIni);
   867→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, GGameUserSettingsIni);
   868→
   869→	CoinBalance = FMath::Max(0, LoadedCoin);
   870→	GemBalance = FMath::Max(0, LoadedGem);
   871→
   872→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
   873→}
   874→
   875→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   876→{
   877→	NewAmount = FMath::Max(0, NewAmount);
   878→
   879→	switch (Type)
   880→	{
   881→	case ECurrencyType::Coin:
   882→		if (CoinBalance != NewAmount)
   883→		{
   884→			CoinBalance = NewAmount;
   885→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   886→		}
   887→		break;
   888→	case ECurrencyType::Gem:
   889→		if (GemBalance != NewAmount)
   890→		{
   891→			GemBalance = NewAmount;
   892→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   893→		}
   894→		break;
   895→	}
   896→}
