   301→
   302→void UWjWorldCosmeticSubsystem::ParseInventoryResult()
   303→{
   304→#if WITH_STEAM
   305→	ISteamInventory* SteamInv = SteamInventory();
   306→	if (!SteamInv)
   307→	{
   308→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: SteamInventory 없음"));
   309→		return;
   310→	}
   311→
   312→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   313→	{
   314→		return;
   315→	}
   316→
   317→	// 아이템 개수 확인
   318→	uint32 ItemCount = 0;
   319→	if (!SteamInv->GetResultItems(PendingResultHandle, nullptr, &ItemCount) || ItemCount == 0)
   320→	{
   321→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리: 아이템 0개"));
   322→		CachedInventory.Empty();
   323→		AllItemQuantities.Empty();
   324→		return;
   325→	}
   326→
   327→	// 아이템 상세 정보 가져오기
   328→	TArray<SteamItemDetails_t> ItemDetails;
   329→	ItemDetails.SetNum(ItemCount);
   330→
   331→	if (!SteamInv->GetResultItems(PendingResultHandle, ItemDetails.GetData(), &ItemCount))
   332→	{
   333→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 아이템 상세 정보 가져오기 실패"));
   334→		return;
   335→	}
   336→
   337→	// 전체 DefId별 수량 캐시 갱신 (배치 오브젝트 소유권 추적용)
   338→	AllItemQuantities.Empty();
   339→	for (uint32 i = 0; i < ItemCount; ++i)
   340→	{
   341→		const SteamItemDetails_t& Details = ItemDetails[i];
   342→		if (Details.m_unQuantity > 0)
   343→		{
   344→			AllItemQuantities.FindOrAdd(Details.m_iDefinition) += Details.m_unQuantity;
   345→		}
   346→	}
   347→
   348→	// 캐시된 코스메틱 인벤토리 갱신 (Catalog 필요)
   349→	CachedInventory.Empty(ItemCount);
   350→
   351→	if (!Catalog)
   352→	{
   353→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: Catalog 없음 — 전체 수량만 캐싱"));
   354→		return;
   355→	}
   356→
   357→	for (uint32 i = 0; i < ItemCount; ++i)
   358→	{
   359→		const SteamItemDetails_t& Details = ItemDetails[i];
   360→
   361→		// 수량 체크 (0이면 소비됨/만료됨)
   362→		if (Details.m_unQuantity == 0)
