   163→void AWjWorldGameModePlay::StartGame(float SecondsForStartCount)
   164→{
   165→	GetGameState<AWjWorldGameStatePlay>()->GameStartWithCountdown(SecondsForStartCount);
   166→	GetGameState<AWjWorldGameStatePlay>()->SetGameRuleClass(CurrentGameRule->GetClass());
   167→
   168→	if(GetWorld() && CurrentGameRule)
   169→	{
   170→		GetWorld()->GetTimerManager().SetTimer(StartGameHandle, FTimerDelegate::CreateLambda([this, SecondsForStartCount]()
   171→		{
   172→			CurrentGameRule->OnGameStart();
   173→			OnGameStart.Broadcast();
   174→		}), SecondsForStartCount, false);
   175→	}
   176→
   177→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: StartGame scheduled in %f seconds"), SecondsForStartCount);
   178→}
