   591→void AWjWorldPlayerControllerBase::Placement_GrantItem(FString ObjectId, int32 Quantity)
   592→{
   593→#if !UE_BUILD_SHIPPING
   594→	if (Quantity <= 0) Quantity = 1;
   595→
   596→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   597→	if (!Settings)
   598→	{
   599→		return;
   600→	}
   601→
   602→	UWjWorldPlaceableObjectDataAsset* Catalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::Lobby);
   603→	if (!Catalog)
   604→	{
   605→		UE_LOG(LogWjWorld, Warning, TEXT("Placement_GrantItem: LobbyPlaceableCatalog 없음"));
   606→		return;
   607→	}
   608→
   609→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(FName(*ObjectId));
   610→	if (!Def)
   611→	{
   612→		UE_LOG(LogWjWorld, Warning, TEXT("Placement_GrantItem: '%s' 카탈로그에 없음"), *ObjectId);
   613→		return;
   614→	}
   615→
   616→	if (Def->SteamItemDefId <= 0)
   617→	{
   618→		UE_LOG(LogWjWorld, Warning, TEXT("Placement_GrantItem: '%s'에 SteamItemDefId 없음"), *ObjectId);
   619→		return;
   620→	}
   621→
   622→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   623→	if (!CosmeticSub)
   624→	{
   625→		UE_LOG(LogWjWorld, Warning, TEXT("Placement_GrantItem: CosmeticSubsystem 없음"));
   626→		return;
   627→	}
   628→
   629→	// AllItemQuantities에 직접 추가 (로컬 테스트용)
   630→	CosmeticSub->AllItemQuantities.FindOrAdd(Def->SteamItemDefId) += Quantity;
   631→
   632→	// 비Steam: GConfig에도 기록
   633→	static const FString PlacementInventorySection = TEXT("PlacementInventory");
   634→	int32 CurrentOwned = 0;
   635→	GConfig->GetInt(*PlacementInventorySection, *ObjectId, CurrentOwned, GGameUserSettingsIni);
   636→	GConfig->SetInt(*PlacementInventorySection, *ObjectId, CurrentOwned + Quantity, GGameUserSettingsIni);
   637→	GConfig->Flush(false, GGameUserSettingsIni);
   638→
   639→	CosmeticSub->OnInventoryUpdated.Broadcast();
   640→
   641→	UE_LOG(LogWjWorld, Log, TEXT("Placement_GrantItem: %s x%d 부여 완료 (DefId: %d)"),
   642→		*ObjectId, Quantity, Def->SteamItemDefId);
   643→#endif
   644→}
