    16→void USessionManager::Initialize()
    17→{
    18→	// Online Subsystem 가져오기 - 우선순위: Steam > NULL
    19→	IOnlineSubsystem* OnlineSubsystem = IOnlineSubsystem::Get(STEAM_SUBSYSTEM);
    20→	if (!OnlineSubsystem)
    21→	{
    22→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Steam subsystem not available, trying NULL subsystem"));
    23→		OnlineSubsystem = IOnlineSubsystem::Get(NULL_SUBSYSTEM);
