    40→			SessionInterface->OnEndSessionCompleteDelegates.AddUObject(this, &USessionManager::OnEndSessionComplete);
    41→
    42→			UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Initialized successfully with %s"), *OnlineSubsystem->GetSubsystemName().ToString());
    43→		}
