   571→bool USessionManager::CreateMigrationSession(const FRoomSettings& Settings, const FString& MigrationTag)
   572→{
   573→	if (!SessionInterface.IsValid())
   574→	{
   575→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   576→		return false;
   577→	}
   578→
   579→	// 기존 세션 제거
   580→	auto ExistingSession = SessionInterface->GetNamedSession(SESSION_NAME);
   581→	if (ExistingSession != nullptr)
   582→	{
   583→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Migration - Destroying existing session..."));
   584→
   585→		SessionInterface->DestroySession(SESSION_NAME);
   586→
   587→		int32 WaitCount = 0;
   588→		while (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr && WaitCount < 100)
   589→		{
   590→			FPlatformProcess::Sleep(0.01f);
   591→			WaitCount++;
   592→		}
   593→
   594→		if (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr)
   595→		{
   596→			UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Migration - Failed to destroy existing session"));
   597→			return false;
   598→		}
   599→	}
   600→
   601→	// 네트워크 모드에 맞게 NetDriver 전환
   602→	ApplyNetDriverForMode(Settings.NetworkMode);
   603→
   604→	// 세션 설정 (CreateSession과 동일하되 MIGRATION_TAG 추가)
   605→	FOnlineSessionSettings SessionSettings;
   606→	SessionSettings.NumPublicConnections = Settings.MaxPlayers;
   607→	SessionSettings.bShouldAdvertise = true;
   608→	SessionSettings.bAllowJoinInProgress = true;
   609→	SessionSettings.bAllowJoinViaPresence = false;
   610→	SessionSettings.bAllowJoinViaPresenceFriendsOnly = false;
   611→
   612→	// 네트워크 모드에 따른 설정
   613→	// Steam: bUsesPresence와 bUseLobbiesIfAvailable은 반드시 같은 값이어야 함
   614→	if (Settings.NetworkMode == ENetworkMode::Steam)
   615→	{
   616→		SessionSettings.bIsLANMatch = false;
   617→		SessionSettings.bUsesPresence = true;
   618→		SessionSettings.bUseLobbiesIfAvailable = true;
   619→	}
   620→	else // LAN
   621→	{
   622→		SessionSettings.bIsLANMatch = true;
   623→		SessionSettings.bUsesPresence = false;
   624→		SessionSettings.bUseLobbiesIfAvailable = false;
   625→	}
   626→
   627→	// 커스텀 데이터 설정
   628→	SessionSettings.Set(FName("ROOM_NAME"), Settings.RoomName, EOnlineDataAdvertisementType::ViaOnlineService);
   629→	SessionSettings.Set(FName("GAME_MODE"), Settings.GameMode, EOnlineDataAdvertisementType::ViaOnlineService);
   630→	SessionSettings.Set(FName("MAP_NAME"), Settings.MapName, EOnlineDataAdvertisementType::ViaOnlineService);
   631→	SessionSettings.Set(FName("IS_PRIVATE"), Settings.bIsPrivate, EOnlineDataAdvertisementType::ViaOnlineService);
   632→
   633→	// 마이그레이션 태그 추가
   634→	SessionSettings.Set(FName("MIGRATION_TAG"), MigrationTag, EOnlineDataAdvertisementType::ViaOnlineService);
   635→
   636→	// 세션 생성
   637→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   638→	bool bSuccess = SessionInterface->CreateSession(*LocalPlayer->GetPreferredUniqueNetId(), SESSION_NAME, SessionSettings);
   639→
   640→	if (bSuccess)
   641→	{
   642→		LastRoomSettings = Settings;
   643→		bIsHost = true;
   644→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Creating migration session '%s' with tag '%s'"),
   645→			*Settings.RoomName, *MigrationTag);
   646→	}
   647→	else
   648→	{
   649→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to create migration session"));
   650→	}
   651→
   652→	return bSuccess;
   653→}
