   239→// ============================================================================
   240→
   241→void UWjWorldGameInstance::BeginHostMigration()
   242→{
   243→	MigrationContext.bIsMigrating = true;
   244→	MigrationContext.MigrationStartTime = FPlatformTime::Seconds();
   245→	MigrationContext.RetryCount = 0;
   246→	SetMigrationState(EHostMigrationState::Detected);
   247→
   248→	// 마이그레이션 태그 생성 (모든 클라이언트 동일)
   249→	MigrationContext.MigrationSessionTag = GenerateMigrationTag();
   250→
   251→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Host migration started - Tag: '%s'"),
   252→		*MigrationContext.MigrationSessionTag);
   253→
   254→	// 기존 세션 파괴
   255→	if (SessionManager)
   256→	{
   257→		SessionManager->DestroySession();
   258→	}
   259→
   260→	// 타임아웃 타이머 설정
   261→	UWorld* World = GetWorld();
   262→	if (World)
   263→	{
   264→		World->GetTimerManager().SetTimer(MigrationTimeoutHandle,
   265→			FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::OnMigrationTimeout),
   266→			FHostMigrationContext::MigrationTimeout, false);
   267→	}
   268→
   269→	// 새 호스트 결정
   270→	MigrationContext.bIsNewHost = DetermineIfNewHost();
   271→
   272→	if (MigrationContext.bIsNewHost)
   273→	{
   274→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is the new host"));
   275→		MigrationCreateSession();
   276→	}
   277→	else
   278→	{
   279→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is NOT the new host - waiting 3s before searching"));
   280→
   281→		// 3초 대기 후 검색 시작
   282→		if (World)
   283→		{
   284→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   285→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   286→				3.0f, false);
   287→		}
   288→	}
   289→}
