   291→bool UWjWorldGameInstance::DetermineIfNewHost() const
   292→{
   293→	const TArray<FPlayerDisplayInfo>& CachedPlayers = MigrationContext.CachedPlayerList;
   294→
   295→	if (CachedPlayers.Num() == 0)
   296→	{
   297→		// 캐시가 비어있으면 자신이 호스트
   298→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: No cached players - assuming new host"));
   299→		return true;
   300→	}
   301→
   302→	// PlayerID 오름차순 정렬 (이전 호스트 제외)
   303→	TArray<FPlayerDisplayInfo> Candidates;
   304→	for (const FPlayerDisplayInfo& Info : CachedPlayers)
   305→	{
   306→		if (!Info.bIsHost) // 이전 호스트 제외
   307→		{
   308→			Candidates.Add(Info);
   309→		}
   310→	}
   311→
   312→	if (Candidates.Num() == 0)
   313→	{
   314→		// 모든 플레이어가 호스트? 자신이 새 호스트
   315→		return true;
   316→	}
   317→
   318→	// PlayerID 오름차순 정렬
   319→	Candidates.Sort([](const FPlayerDisplayInfo& A, const FPlayerDisplayInfo& B)
   320→	{
   321→		return A.PlayerID < B.PlayerID;
   322→	});
   323→
   324→	// 첫 번째 = 새 호스트
   325→	return (Candidates[0].PlayerID == MigrationContext.LocalPlayerID);
   326→}
