   328→FString UWjWorldGameInstance::GenerateMigrationTag() const
   329→{
   330→	// 결정론적 태그: "MIG_{RoomName}_{OriginalHostPlayerID}"
   331→	FString RoomName = MigrationContext.CachedRoomSettings.RoomName;
   332→	int32 OriginalHostID = -1;
   333→
   334→	for (const FPlayerDisplayInfo& Info : MigrationContext.CachedPlayerList)
   335→	{
   336→		if (Info.bIsHost)
   337→		{
   338→			OriginalHostID = Info.PlayerID;
   339→			break;
   340→		}
   341→	}
   342→
   343→	return FString::Printf(TEXT("MIG_%s_%d"), *RoomName, OriginalHostID);
   344→}
