   346→void UWjWorldGameInstance::MigrationCreateSession()
   347→{
   348→	SetMigrationState(EHostMigrationState::CreatingSession);
   349→
   350→	if (!SessionManager)
   351→	{
   352→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationCreateSession - SessionManager is null"));
   353→		MigrationFailed();
   354→		return;
   355→	}
   356→
   357→	// 콜백 바인딩
   358→	SessionManager->OnRoomCreatedEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   359→
   360→	bool bSuccess = SessionManager->CreateMigrationSession(
   361→		MigrationContext.CachedRoomSettings,
   362→		MigrationContext.MigrationSessionTag);
   363→
   364→	if (!bSuccess)
   365→	{
   366→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   367→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to create migration session"));
   368→		MigrationRetryOrFail();
   369→	}
   370→}
   371→
   372→void UWjWorldGameInstance::OnMigrationSessionCreated(bool bWasSuccessful)
   373→{
   374→	if (SessionManager)
   375→	{
   376→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   377→	}
   378→
   379→	if (bWasSuccessful)
   380→	{
   381→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session created - ServerTraveling to WaitingRoom"));
   382→		SetMigrationState(EHostMigrationState::Complete);
   383→
   384→		UWorld* World = GetWorld();
   385→		if (World)
   386→		{
   387→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   388→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   389→			World->ServerTravel(Settings->GetWaitingRoomOpenLevelURL());
   390→		}
   391→	}
   392→	else
   393→	{
   394→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration session creation failed"));
   395→		MigrationRetryOrFail();
   396→	}
   397→}
