    55→	if (CachedGameState)
    56→	{
    57→		// ⭐ 디버깅: GameState 정보 로그
    58→		int32 PlayerCount = CachedGameState->GetPlayerCount();
    59→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: GameState found! PlayerCount = %d"), PlayerCount);
    60→		
    61→		// PlayerArray 내용 확인
    62→		for (int32 i = 0; i < CachedGameState->PlayerArray.Num(); i++)
    63→		{
    64→			APlayerState* PS = CachedGameState->PlayerArray[i];
    65→			if (PS)
