    67→				UE_LOG(LogWjWorld, Warning, TEXT("  - PlayerState[%d]: %s (ID: %d)"), 
    68→					i, *PS->GetPlayerName(), PS->GetPlayerId());
    69→			}
    70→		}
    71→
    72→		// 델리게이트 바인딩
    73→		CachedGameState->OnRoomInfoChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnRoomInfoChanged);
    74→		CachedGameState->OnPlayerListChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnPlayerListChanged);
