    86→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: GameState events bound"));
    87→	}
    88→	else
    89→	{
    90→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to get GameStateWaitingRoom"));
    91→	}
    92→
    93→	// PlayerState 이벤트 바인딩
    94→	APlayerController* PC = GetOwningPlayer();
    95→	if (PC)
    96→	{
    97→		AWjWorldPlayerStateBase* PlayerState = PC->GetPlayerState<AWjWorldPlayerStateBase>();
    98→		if (PlayerState)
