   100→			PlayerState->OnReadyStateChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnPlayerReadyStateChanged);
   101→			UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: PlayerState events bound - %s"), *PlayerState->GetPlayerName());
   102→		}
   103→		else
