   513→		// 호스트는 모든 플레이어가 준비되었을 때만 게임 시작 가능
   514→		bool bAllReady = CachedGameState->AreAllPlayersReady();
   515→		int32 PlayerCount = CachedGameState->GetPlayerCount();
