   145→void AWjWorldGameModeWaitingRoom::StartGame()
   146→{
   147→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Starting game..."));
   148→
   149→	// GameInstance를 통해 세션 시작
   150→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   151→	if (!GameInstance)
   152→	{
   153→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeWaitingRoom: GameInstance is null"));
   154→		return;
   155→	}
   156→
   157→	bool bSuccess = GameInstance->StartGame();
   158→	if (!bSuccess)
   159→	{
   160→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameModeWaitingRoom: Failed to start session"));
   161→		return;
   162→	}
   163→
   164→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Session start initiated"));
   165→
   166→	// ⭐ GameState에서 현재 RoomSettings 가져오기 (UI에서 업데이트된 값)
   167→	FRoomSettings Settings;
   168→	AWjWorldGameStateWaitingRoom* WjGameState = GetGameState<AWjWorldGameStateWaitingRoom>();
   169→	if (WjGameState)
   170→	{
   171→		Settings = WjGameState->GetRoomSettings();
   172→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Using GameState settings - GameMode: '%s', Map: '%s'"),
   173→			*Settings.GameMode, *Settings.MapName);
   174→	}
   175→	else if (GameInstance->GetSessionManager())
   176→	{
   177→		// 폴백: SessionManager에서 가져오기
   178→		Settings = GameInstance->GetSessionManager()->GetLastRoomSettings();
   179→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Fallback to SessionManager settings - GameMode: '%s', Map: '%s'"),
   180→			*Settings.GameMode, *Settings.MapName);
   181→	}
   182→
   183→	// 카탈로그에서 LevelPath 조회
   184→	FString TravelURL;
   185→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   186→	if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
   187→	{
   188→		UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   189→		if (Catalog)
   190→		{
   191→			const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*Settings.GameMode));
   192→			if (Def)
   193→			{
   194→				// LevelPath + GameMode 명시적 지정 + GameModeId 전달 (GameRule 조회용)
   195→				TravelURL = DevSettings->GetPlayServerTravelURL(Def->LevelPath, Settings.GameMode);
   196→
   197→				// MapOption을 URL 옵션으로 전달
   198→				if (!Settings.MapName.IsEmpty())
   199→				{
   200→					TravelURL += FString::Printf(TEXT("?MapOption=%s"), *Settings.MapName);
   201→				}
   202→
   203→				UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameModeWaitingRoom: Travel to '%s' (GameModeId: %s)"),
   204→					*TravelURL, *Settings.GameMode);
   205→			}
   206→			else
   207→			{
   208→				UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: GameModeId '%s' not found in catalog"), *Settings.GameMode);
   209→			}
   210→		}
   211→	}
   212→
   213→	// 폴백: 카탈로그에서 못 찾으면 기본 경로 사용
   214→	if (TravelURL.IsEmpty())
   215→	{
   216→		TravelURL = TEXT("/Game/Map/03-1_ApproachingWall");
   217→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameModeWaitingRoom: Using fallback travel URL: %s"), *TravelURL);
   218→	}
   219→
   220→	GetWorld()->ServerTravel(TravelURL);
   221→}
