   249→void AWjWorldGameModeWaitingRoom::LoadHostLayoutToGameState()
   250→{
   251→	if (!HasAuthority())
   252→	{
   253→		return;
   254→	}
   255→
   256→	AWjWorldGameStateWaitingRoom* WaitingRoomGameState = GetGameState<AWjWorldGameStateWaitingRoom>();
   257→	if (!WaitingRoomGameState)
   258→	{
   259→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WjWorldGameModeWaitingRoom: GameState not found"));
   260→		return;
   261→	}
   262→
   263→	// 호스트의 로컬 SaveGame 로드
   264→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   265→		UGameplayStatics::LoadGameFromSlot(TEXT("LobbyLayout"), 0)
   266→	);
   267→
   268→	if (SaveGame && SaveGame->PlacedObjects.Num() > 0)
   269→	{
   270→		WaitingRoomGameState->SetPlacedObjects(SaveGame->PlacedObjects);
   271→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: Host layout loaded to GameState (%d objects)"),
   272→			SaveGame->PlacedObjects.Num());
   273→	}
   274→	else
   275→	{
   276→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: No saved layout found for host"));
   277→	}
   278→}
