     7→void UConfirmDialogWidget::NativeConstruct()
     8→{
     9→	Super::NativeConstruct();
    10→
    11→	if (ConfirmButton)
    12→	{
    13→		ConfirmButton->OnClicked.AddDynamic(this, &UConfirmDialogWidget::OnConfirmClicked);
    14→	}
    15→
    16→	if (CancelButton)
    17→	{
    18→		CancelButton->OnClicked.AddDynamic(this, &UConfirmDialogWidget::OnCancelClicked);
    19→	}
    20→
    21→	// NativeConstruct 이전에 SetMessage/SetButtonLabels가 호출되었으면 재적용
    22→	if (bMessageSet && MessageText)
    23→	{
    24→		MessageText->SetText(CachedMessage);
    25→	}
    26→
    27→	if (bLabelsSet)
    28→	{
    29→		if (ConfirmButtonText)
    30→		{
    31→			ConfirmButtonText->SetText(CachedConfirmLabel);
    32→		}
    33→		if (CancelButtonText)
    34→		{
    35→			CancelButtonText->SetText(CachedCancelLabel);
    36→		}
    37→	}
    38→}
    39→
