    50→void UConfirmDialogWidget::SetMessage(const FText& InMessage)
    51→{
    52→	CachedMessage = InMessage;
    53→	bMessageSet = true;
    54→
    55→	if (MessageText)
    56→	{
    57→		MessageText->SetText(InMessage);
    58→	}
    59→}
    60→
    61→void UConfirmDialogWidget::SetButtonLabels(const FText& ConfirmLabel, const FText& CancelLabel)
    62→{
    63→	CachedConfirmLabel = ConfirmLabel;
    64→	CachedCancelLabel = CancelLabel;
    65→	bLabelsSet = true;
    66→
    67→	if (ConfirmButtonText)
    68→	{
    69→		ConfirmButtonText->SetText(ConfirmLabel);
    70→	}
    71→	if (CancelButtonText)
    72→	{
    73→		CancelButtonText->SetText(CancelLabel);
    74→	}
    75→}
    76→
    77→void UConfirmDialogWidget::OnConfirmClicked()
    78→{
    79→	OnConfirmed.Broadcast();
    80→	ClosePopup();
    81→}
    82→
    83→void UConfirmDialogWidget::OnCancelClicked()
    84→{
    85→	OnCancelled.Broadcast();
    86→	ClosePopup();
    87→}
