   466→void AWjWorldPlayerControllerBase::Steam_GrantCoin(int32 Count)
   467→{
   468→#if !UE_BUILD_SHIPPING && WITH_STEAM
   469→	ISteamInventory* SteamInv = SteamInventory();
   470→	if (!SteamInv)
   471→	{
   472→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam_GrantCoin: Steam Inventory 사용 불가"));
   473→		return;
   474→	}
   475→
   476→	if (Count < 1) Count = 1;
   477→
   478→	// GenerateItems: 퍼블리셔 계정 전용 개발 API — 아이템 직접 생성
   479→	SteamItemDef_t ItemDef = 1000; // WjCoin
   480→	uint32 Quantity = static_cast<uint32>(Count);
   481→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   482→
   483→	if (SteamInv->GenerateItems(&ResultHandle, &ItemDef, &Quantity, 1))
   484→	{
   485→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam_GrantCoin: GenerateItems 성공 (%d코인)"), Count);
   486→		SteamInv->DestroyResult(ResultHandle);
   487→
   488→		// Steam 서버 반영 대기 후 인벤토리 갱신 (즉시 호출 시 아직 반영 안 됨)
   489→		FTimerHandle TimerHandle;
   490→		GetWorldTimerManager().SetTimer(TimerHandle, [WeakThis = TWeakObjectPtr<AWjWorldPlayerControllerBase>(this)]()
   491→		{
   492→			if (AWjWorldPlayerControllerBase* PC = WeakThis.Get())
   493→			{
   494→				UWjWorldCosmeticSubsystem* CosmeticSub = PC->GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   495→				if (CosmeticSub)
   496→				{
   497→					CosmeticSub->RequestInventoryRefresh();
   498→				}
   499→				UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam_GrantCoin: 지연 인벤토리 갱신 완료"));
   500→			}
   501→		}, 1.5f, false);
   502→	}
   503→	else
   504→	{
   505→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam_GrantCoin: GenerateItems 실패 (퍼블리셔 계정 필요)"));
   506→	}
   507→#else
   508→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam_GrantCoin: Steam 빌드에서만 사용 가능"));
   509→#endif
   510→}
