   557→		return;
   558→	}
   559→
   560→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   561→	if (!Settings)
   562→	{
   563→		return;
   564→	}
   565→
   566→	UWjWorldPlaceableObjectDataAsset* Catalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::Lobby);
   567→	if (!Catalog)
   568→	{
   569→		UE_LOG(LogWjWorld, Warning, TEXT("Placement_PrintInventory: LobbyPlaceableCatalog 없음"));
