   159→
   160→void UWjWorldGameInstance::HandleNetworkFailure(UWorld* World, UNetDriver* NetDriver,
   161→	ENetworkFailure::Type FailureType, const FString& ErrorString)
   162→{
   163→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleNetworkFailure called - Type: %d, Error: %s"),
   164→		static_cast<int32>(FailureType), *ErrorString);
   165→
   166→	// 이미 마이그레이션 중이면 무시
   167→	if (MigrationContext.bIsMigrating)
   168→	{
   169→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure ignored - already migrating"));
   170→		return;
   171→	}
   172→
   173→	// 자신이 호스트(서버)면 마이그레이션 불필요
   174→	if (World && World->GetAuthGameMode() != nullptr)
   175→	{
   176→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure on server - ignoring (Type: %d, Error: %s)"),
   177→			static_cast<int32>(FailureType), *ErrorString);
   178→		return;
   179→	}
   180→
   181→	// 연결 관련 Failure 타입은 모두 마이그레이션 시도
   182→	// (Steam P2P에서는 다양한 에러 타입이 발생할 수 있음)
   183→	switch (FailureType)
   184→	{
   185→	case ENetworkFailure::ConnectionLost:
   186→	case ENetworkFailure::FailureReceived:
   187→	case ENetworkFailure::ConnectionTimeout:
   188→	case ENetworkFailure::PendingConnectionFailure:
   189→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure detected - Type: %d, Error: %s. Beginning host migration."),
   190→			static_cast<int32>(FailureType), *ErrorString);
   191→		BeginHostMigration();
   192→		break;
   193→	default:
   194→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure type %d not handled for migration"),
   195→			static_cast<int32>(FailureType));
   196→		break;
   197→	}
   198→}
   199→
   200→void UWjWorldGameInstance::HandleTravelFailure(UWorld* World, ETravelFailure::Type FailureType, const FString& ErrorString)
   201→{
   202→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleTravelFailure called - Type: %d, Error: %s"),
   203→		static_cast<int32>(FailureType), *ErrorString);
   204→
   205→	// 이미 마이그레이션 중이면 무시
   206→	if (MigrationContext.bIsMigrating)
   207→	{
   208→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: TravelFailure ignored - already migrating"));
   209→		return;
   210→	}
   211→
   212→	// 자신이 호스트(서버)면 마이그레이션 불필요
   213→	if (World && World->GetAuthGameMode() != nullptr)
   214→	{
   215→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure on server - ignoring"));
   216→		return;
   217→	}
   218→
   219→	// ServerTravel 실패 시 호스트 마이그레이션 시도
   220→	switch (FailureType)
   221→	{
   222→	case ETravelFailure::ServerTravelFailure:
   223→	case ETravelFailure::ClientTravelFailure:
   224→	case ETravelFailure::TravelFailure:
   225→	case ETravelFailure::PackageMissing:
   226→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: TravelFailure detected - Type: %d. Beginning host migration."),
   227→			static_cast<int32>(FailureType));
   228→		BeginHostMigration();
   229→		break;
   230→	default:
   231→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure type %d not handled for migration"),
   232→			static_cast<int32>(FailureType));
   233→		break;
   234→	}
   235→}
