   399→void UWjWorldGameInstance::MigrationSearchForNewHost()
   400→{
   401→	SetMigrationState(EHostMigrationState::SearchingSession);
   402→
   403→	if (!SessionManager)
   404→	{
   405→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationSearchForNewHost - SessionManager is null"));
   406→		MigrationFailed();
   407→		return;
   408→	}
   409→
   410→	// 콜백 바인딩
   411→	SessionManager->OnRoomsFoundEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   412→
   413→	bool bSuccess = SessionManager->FindMigrationSession(MigrationContext.MigrationSessionTag);
   414→
   415→	if (!bSuccess)
   416→	{
   417→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   418→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to start migration session search"));
   419→		MigrationRetryOrFail();
   420→	}
   421→}
   422→
   423→void UWjWorldGameInstance::OnMigrationSearchResult(bool bWasSuccessful, const TArray<FRoomInfo>& Rooms)
   424→{
   425→	if (SessionManager)
   426→	{
   427→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   428→	}
   429→
   430→	if (bWasSuccessful)
   431→	{
   432→		// JoinSession은 FindMigrationSession 내부에서 자동으로 호출됨
   433→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session found and joining"));
   434→		SetMigrationState(EHostMigrationState::JoiningSession);
   435→
   436→		UWorld* World = GetWorld();
   437→		if (World)
   438→		{
   439→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   440→		}
   441→		// JoinSession → ClientTravel이 자동으로 발생
   442→	}
   443→	else
   444→	{
   445→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration session not found - will retry"));
   446→		MigrationRetryOrFail();
   447→	}
   448→}
   449→
   450→void UWjWorldGameInstance::MigrationRetryOrFail()
   451→{
   452→	MigrationContext.RetryCount++;
   453→
   454→	// 타임아웃 체크
   455→	double ElapsedTime = FPlatformTime::Seconds() - MigrationContext.MigrationStartTime;
   456→	if (ElapsedTime >= FHostMigrationContext::MigrationTimeout)
   457→	{
   458→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timed out after %.1f seconds"), ElapsedTime);
   459→		MigrationFailed();
   460→		return;
   461→	}
   462→
   463→	// 최대 재시도 횟수 체크
   464→	if (MigrationContext.RetryCount >= FHostMigrationContext::MaxRetryCount)
   465→	{
   466→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration max retries (%d) reached"), FHostMigrationContext::MaxRetryCount);
   467→		MigrationFailed();
   468→		return;
   469→	}
   470→
   471→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration retry %d/%d in %.1f seconds"),
   472→		MigrationContext.RetryCount, FHostMigrationContext::MaxRetryCount, FHostMigrationContext::RetryInterval);
   473→
   474→	UWorld* World = GetWorld();
   475→	if (World)
   476→	{
   477→		if (MigrationContext.bIsNewHost)
   478→		{
   479→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   480→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationCreateSession),
   481→				FHostMigrationContext::RetryInterval, false);
   482→		}
   483→		else
   484→		{
   485→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   486→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   487→				FHostMigrationContext::RetryInterval, false);
   488→		}
   489→	}
   490→}
   491→
   492→void UWjWorldGameInstance::OnMigrationTimeout()
   493→{
   494→	UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timeout (%.0f seconds)"),
   495→		FHostMigrationContext::MigrationTimeout);
   496→	MigrationFailed();
   497→}
   498→
   499→void UWjWorldGameInstance::MigrationFailed()
   500→{
   501→	SetMigrationState(EHostMigrationState::Failed);
   502→
   503→	UWorld* World = GetWorld();
   504→	if (World)
   505→	{
   506→		World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   507→		World->GetTimerManager().ClearTimer(MigrationRetryHandle);
   508→	}
   509→
   510→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration failed - returning to lobby"));
   511→
   512→	// 세션 정리
   513→	if (SessionManager)
   514→	{
   515→		SessionManager->DestroySession();
   516→	}
   517→
   518→	// 마이그레이션 컨텍스트 리셋
   519→	MigrationContext.Reset();
   520→	SetMigrationState(EHostMigrationState::None);
   521→
   522→	// 로비로 복귀
   523→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   524→	UGameplayStatics::OpenLevel(this, FName(*Settings->GetLobbyMapPath()));
   525→}
   526→
   527→void UWjWorldGameInstance::SetMigrationState(EHostMigrationState NewState)
   528→{
   529→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration state: %d → %d"),
   530→		static_cast<int32>(MigrationState), static_cast<int32>(NewState));
   531→	MigrationState = NewState;
   532→}
