   171→		{
   172→			CurrentGameRule->OnGameStart();
   173→			OnGameStart.Broadcast();
   174→		}), SecondsForStartCount, false);
   175→	}
   176→
   177→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: StartGame scheduled in %f seconds"), SecondsForStartCount);
