   257→void UWaitingRoomHUDWidget::UpdateRoomInfo(const FRoomSettings* InSettings)
   258→{
   259→	// 설정이 직접 전달되면 사용, 아니면 GameState에서 읽음
   260→	FRoomSettings Settings;
   261→	if (InSettings)
   262→	{
   263→		Settings = *InSettings;
   264→	}
   265→	else if (CachedGameState)
   266→	{
   267→		Settings = CachedGameState->GetRoomSettings();
   268→	}
   269→	else
   270→	{
   271→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - CachedGameState is NULL"));
   272→		return;
   273→	}
   274→
   275→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - Updating with: RoomName='%s', GameMode='%s', MapName='%s'"),
   276→		*Settings.RoomName, *Settings.GameMode, *Settings.MapName);
   277→
   278→	// 방 이름 표시
   279→	if (RoomNameText)
   280→	{
   281→		RoomNameText->SetText(FText::FromString(Settings.RoomName));
   282→	}
   283→
   284→	// 게임 모드 표시
   285→	if (GameModeText)
   286→	{
   287→		GameModeText->SetText(FText::FromString(Settings.GameMode));
   288→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: GameModeText set to '%s'"), *Settings.GameMode);
   289→	}
   290→
   291→	// 맵 이름 표시
   292→	if (MapText)
   293→	{
   294→		FString MapDisplayName = Settings.MapName;
   295→		// User_ 접두사 제거하여 표시
   296→		MapDisplayName.RemoveFromStart(TEXT("User_"));
   297→		MapText->SetText(FText::FromString(MapDisplayName));
   298→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: MapText set to '%s'"), *MapDisplayName);
   299→	}
   300→
   301→	// ⭐ 플레이어 수 표시 (실시간으로 가져오기)
   302→	if (PlayerCountText && CachedGameState)
   303→	{
   304→		int32 CurrentPlayers = CachedGameState->GetPlayerCount();
   305→		int32 MaxPlayers = Settings.MaxPlayers;
   306→
   307→		FString PlayerCountStr = FString::Printf(TEXT("%d / %d"), CurrentPlayers, MaxPlayers);
   308→		PlayerCountText->SetText(FText::FromString(PlayerCountStr));
   309→
   310→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: PlayerCountText set to '%s'"), *PlayerCountStr);
   311→	}
   312→
   313→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Room info updated successfully"));
   314→}
