   316→void UWaitingRoomHUDWidget::UpdatePlayerList()
   317→{
   318→	if (!CachedGameState || !PlayerListContainer)
   319→	{
   320→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdatePlayerList - GameState or Container is NULL"));
   321→		return;
   322→	}
   323→
   324→	// 기존 목록 제거
   325→	PlayerListContainer->ClearChildren();
   326→	PlayerButtonToIDMap.Empty();
   327→
   328→	// 플레이어 목록 가져오기 & 캐시
   329→	CachedPlayerDisplayList = CachedGameState->GetPlayerList();
   330→
   331→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Updating player list - %d players"), CachedPlayerDisplayList.Num());
   332→
   333→	// 버튼으로 표시 (클릭 시 프로필 팝업)
   334→	for (const FPlayerDisplayInfo& Info : CachedPlayerDisplayList)
   335→	{
   336→		UButton* PlayerButton = NewObject<UButton>(this);
   337→		if (!PlayerButton)
   338→		{
   339→			continue;
   340→		}
   341→
   342→		// 버튼 안에 텍스트 추가
   343→		UTextBlock* PlayerText = NewObject<UTextBlock>(this);
   344→		if (PlayerText)
   345→		{
   346→			FString DisplayText = Info.PlayerName;
   347→
   348→			if (Info.bIsHost)
   349→			{
   350→				DisplayText = FString::Printf(TEXT("[Host] %s"), *DisplayText);
   351→			}
   352→
   353→			if (Info.bIsReady)
   354→			{
   355→				DisplayText += TEXT(" (Ready)");
   356→			}
   357→
   358→			PlayerText->SetText(FText::FromString(DisplayText));
   359→			PlayerButton->AddChild(PlayerText);
   360→		}
   361→
   362→		// 버튼 → PlayerID 매핑 저장
   363→		PlayerButtonToIDMap.Add(PlayerButton, Info.PlayerID);
   364→
   365→		// 모든 버튼에 공통 핸들러 바인딩
