   579→void UWaitingRoomHUDWidget::UpdateHostSettingsPanelVisibility()
   580→{
   581→	if (!HostSettingsPanel)
   582→	{
   583→		return;
   584→	}
   585→
   586→	bool bIsHost = false;
   587→
   588→	// 1. SessionManager에서 호스트 여부 확인
   589→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   590→	if (GameInstance && GameInstance->GetSessionManager())
   591→	{
   592→		bIsHost = GameInstance->GetSessionManager()->IsHost();
   593→	}
   594→
   595→	// 2. 추가 검증: Listen Server인지 확인 (클라이언트에서 잘못된 bIsHost 값 방지)
   596→	UWorld* World = GetWorld();
   597→	if (World)
   598→	{
   599→		ENetMode NetMode = World->GetNetMode();
   600→		// 클라이언트(NM_Client)는 절대 호스트가 아님
   601→		if (NetMode == NM_Client)
   602→		{
   603→			bIsHost = false;
   604→		}
   605→		// Listen Server(NM_ListenServer)만 호스트임
   606→		else if (NetMode == NM_ListenServer || NetMode == NM_DedicatedServer)
   607→		{
   608→			// SessionManager 값 유지
   609→		}
   610→		else if (NetMode == NM_Standalone)
   611→		{
   612→			// 싱글플레이는 호스트 설정 불필요
   613→			bIsHost = false;
   614→		}
   615→	}
   616→
   617→	// 호스트만 설정 패널 표시 (클라이언트는 Display Text로 확인)
   618→	HostSettingsPanel->SetVisibility(bIsHost ? ESlateVisibility::Visible : ESlateVisibility::Collapsed);
   619→
   620→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: HostSettingsPanel visible=%s (bIsHost=%d, NetMode=%d)"),
   621→		bIsHost ? TEXT("Yes") : TEXT("No"), bIsHost, World ? (int32)World->GetNetMode() : -1);
   622→}
