{
    Super::BeginPlay();
    SetInputMode(FInputModeGameOnly());
}

void AWjWorldPlayerControllerPlay::SetupInputComponent()
{
    Super::SetupInputComponent();

    // ESC 키를 PlayerController의 InputComponent에 직접 바인딩
    // (IMC/Pawn 무관하게 동작)
    if (InputComponent)
    {
        InputComponent->BindKey(EKeys::Escape, IE_Pressed, this,
            &AWjWorldPlayerControllerPlay::OnEscapePressed);
    }
}

void AWjWorldPlayerControllerPlay::OnEscapePressed()
{
    // 다이얼로그가 열려있으면 닫기 (ESC == 취소)
    if (bIsLeaveDialogOpen)
    {
        CloseLeaveGameDialog();
        return;
    }

    // 다이얼로그가 닫혀있으면 열기
    ShowLeaveGameDialog();
}

void AWjWorldPlayerControllerPlay::ShowLeaveGameDialog()
{
    if (bIsLeaveDialogOpen)
    {
        return;
    }

    if (!LeaveGameDialogClass)
    {
        UE_LOG(LogWjWorld, Warning, TEXT("PlayerControllerPlay: LeaveGameDialogClass 미설정"));
        return;
    }

    // 로컬 플레이어만 (서버의 AI 컨트롤러 등 무시)
    if (!IsLocalController())
    {
        return;
    }

    // 다이얼로그 생성 (재사용하지 않고 매번 생성 — ConfirmDialogWidget의
    // ClosePopup()이 RemoveFromParent를 호출하므로 재사용 시 NativeConstruct 재호출 이슈)
    LeaveGameDialog = CreateWidget<UConfirmDialogWidget>(this, LeaveGameDialogClass);
    if (!LeaveGameDialog)
    {
        UE_LOG(LogWjWorld, Error, TEXT("PlayerControllerPlay: LeaveGameDialog 생성 실패"));
        return;
    }

    // 메시지 및 버튼 텍스트 설정 (NativeConstruct 전 호출 캐시 패턴 활용)
    LeaveGameDialog->SetMessage(FText::FromString(TEXT("게임을 나가시겠습니까?")));
    LeaveGameDialog->SetButtonLabels(
        FText::FromString(TEXT("나가기")),
        FText::FromString(TEXT("취소"))
    );

    // 델리게이트 바인딩
    LeaveGameDialog->OnConfirmed.AddDynamic(this, &AWjWorldPlayerControllerPlay::OnLeaveGameConfirmed);
    LeaveGameDialog->OnCancelled.AddDynamic(this, &AWjWorldPlayerControllerPlay::OnLeaveGameCancelled);

    // 팝업 표시 (ZOrder 200으로 최상위)
    LeaveGameDialog->ShowPopup();

    // 입력 모드 변경: UI + 게임 (마우스 커서 활성화, 하지만 게임 입력도 유지 — ESC 바인딩 유지를 위해)
    FInputModeGameAndUI InputMode;
    InputMode.SetLockMouseToViewportBehavior(EMouseLockMode::DoNotLock);
    SetInputMode(InputMode);
    bShowMouseCursor = true;

    bIsLeaveDialogOpen = true;

    UE_LOG(LogWjWorld, Log, TEXT("PlayerControllerPlay: 나가기 다이얼로그 표시"));
}

void AWjWorldPlayerControllerPlay::CloseLeaveGameDialog()
{
    if (LeaveGameDialog)
    {
        LeaveGameDialog->OnConfirmed.RemoveDynamic(this, &AWjWorldPlayerControllerPlay::OnLeaveGameConfirmed);
        LeaveGameDialog->OnCancelled.RemoveDynamic(this, &AWjWorldPlayerControllerPlay::OnLeaveGameCancelled);
        LeaveGameDialog->ClosePopup();
        LeaveGameDialog = nullptr;
    }

    // 입력 모드 복원: 게임 전용
    SetInputMode(FInputModeGameOnly());
    bShowMouseCursor = false;

    bIsLeaveDialogOpen = false;

    UE_LOG(LogWjWorld, Log, TEXT("PlayerControllerPlay: 나가기 다이얼로그 닫기"));
}

void AWjWorldPlayerControllerPlay::OnLeaveGameConfirmed()
{
    UE_LOG(LogWjWorld, Log, TEXT("PlayerControllerPlay: 나가기 확인"));
    bIsLeaveDialogOpen = false;
    LeaveGameDialog = nullptr; // ClosePopup()은 OnConfirmClicked에서 이미 호출됨
    ExecuteLeaveGame();
}

void AWjWorldPlayerControllerPlay::OnLeaveGameCancelled()
{
    UE_LOG(LogWjWorld, Log, TEXT("PlayerControllerPlay: 나가기 취소"));

    // 입력 모드 복원
    SetInputMode(FInputModeGameOnly());
    bShowMouseCursor = false;

    bIsLeaveDialogOpen = false;
    LeaveGameDialog = nullptr; // ClosePopup()은 OnCancelClicked에서 이미 호출됨
}

void AWjWorldPlayerControllerPlay::ExecuteLeaveGame()
{
    // WaitingRoom의 OnLeaveClicked() 패턴과 동일
    UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
    if (GameInstance)
    {
        GameInstance->LeaveRoom();
    }

    // 로비로 이동
    const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    UGameplayStatics::OpenLevel(GetWorld(), FName(*Settings->GetLobbyMapPath()));
}
```

**Critical implementation details:**

1. **`SetupInputComponent()` override on PlayerController**: This is the correct place to bind keys at the controller level. The PlayerController's `InputComponent` is created before `SetupInputComponent()` is called, and it persists even when the pawn is destroyed/eliminated. The `BindKey` call does not require Enhanced Input infrastructure.

2. **Widget lifecycle**: `ConfirmDialogWidget::OnConfirmClicked()` and `OnCancelClicked()` both call `ClosePopup()` (which calls `RemoveFromParent()`) before broadcasting the delegate. So by the time `OnLeaveGameConfirmed`/`OnLeaveGameCancelled` fire, the widget is already removed from the viewport. We just need to null out the pointer and reset state.

3. **Input mode management**: When the dialog opens, we switch to `FInputModeGameAndUI` so the mouse cursor appears and can click buttons, but game-level key bindings (like ESC on the controller's InputComponent) still work. On close, we restore `FInputModeGameOnly`.

4. **ESC while dialog is open**: The `OnEscapePressed` function checks `bIsLeaveDialogOpen` first. If the dialog is open, it calls `CloseLeaveGameDialog()` which manually closes the dialog and clears the delegate bindings. This is distinct from the "Cancel" button path but achieves the same result.

5. **Leave logic**: Follows the exact same pattern as `WaitingRoomHUDWidget::OnLeaveClicked()` at line 178-204: `GameInstance->LeaveRoom()` then `OpenLevel(LobbyMap)`. `LeaveRoom()` calls `SessionManager->DestroySession()` which handles both host and client cases.

#### Step 3: Blueprint Configuration

In the Blueprint subclass of `PlayerControllerPlay` (the one referenced in `BP_GameModePlay`):

1. Set `LeaveGameDialogClass` to `WBP_ConfirmDialog` (the existing Blueprint widget at `Content/UI/Blueprint/Common/WBP_ConfirmDialog`).

This is a single property assignment in the BP editor's Details panel.

#### Step 4: No InputAction/IMC Changes Required

Since we use `BindKey(EKeys::Escape)` directly on the PlayerController's InputComponent, there is no need to:
- Create a new `IA_Escape` InputAction asset
- Modify `IMC_Default`
- Add any new DeveloperSettings entries

This is the minimal-change approach.

### Edge Cases and Considerations

**1. Host vs Client Leave:**
- `GameInstance->LeaveRoom()` calls `SessionManager->DestroySession()`. For the host, this will cause all clients to get a `NetworkFailure` which triggers host migration (as implemented in `WjWorldGameInstance::HandleNetworkFailure`). For clients, it simply disconnects them. The `OpenLevel()` call then loads the lobby map locally, cleaning up the listen server / client connection.

**2. Game phase considerations:**
- The feature works in all game phases (Ready, Playing, Finished). A player should be able to leave at any time. The `GameModePlay::Logout()` already notifies the GameRule via `OnPlayerLeft()`, so game logic will handle the departure correctly.

**3. Eliminated players:**
- Since the ESC binding is on the PlayerController's InputComponent (not the pawn's), it works even after the pawn is destroyed or disabled. This is a key advantage of binding at the controller level.

**4. Multiple ESC presses:**
- The `bIsLeaveDialogOpen` guard prevents multiple dialogs from stacking.

**5. Widget memory:**
- A new widget is created each time the dialog is shown. Since `ClosePopup()` calls `RemoveFromParent()`, the widget is eligible for GC. The `UPROPERTY()` pointer (`LeaveGameDialog`) is set to `nullptr` after close, allowing GC. An alternative would be to cache and reuse the widget, but that adds complexity around re-binding delegates and the NativeConstruct timing. Creating a fresh widget each time is simpler and consistent with how `ConfirmDialogWidget` is used elsewhere (the Placement system creates it once and reuses it, but that widget lives for the entire Placement session, whereas this dialog is brief and infrequent).

**6. Server authority:**
- `ExecuteLeaveGame()` runs on the local client only. `LeaveRoom()` handles session teardown. There is no Server RPC needed -- the client simply disconnects. The server's `GameModePlay::Logout()` handles cleanup on the server side automatically when the connection drops.

### Files to Create/Modify Summary

| File | Action | Description |
|------|--------|-------------|
| `Source/WjWorld/Core/Play/WjWorldPlayerControllerPlay.h` | **Modify** | Add ESC handling, dialog management members |
| `Source/WjWorld/Core/Play/WjWorldPlayerControllerPlay.cpp` | **Modify** | Implement SetupInputComponent, dialog show/hide/confirm/cancel, leave logic |
| BP subclass of PlayerControllerPlay | **Modify (BP)** | Set `LeaveGameDialogClass = WBP_ConfirmDialog` |

No new C++ files, no new InputAction assets, no IMC modifications, no DeveloperSettings changes.

### Critical Files for Implementation
- `C:\UEProjects\WjWorld\Source\WjWorld\Core\Play\WjWorldPlayerControllerPlay.h` - Primary file to modify: add ESC handling and dialog management declarations
- `C:\UEProjects\WjWorld\Source\WjWorld\Core\Play\WjWorldPlayerControllerPlay.cpp` - Primary file to modify: implement all ESC/dialog/leave logic
- `C:\UEProjects\WjWorld\Source\WjWorld\UI\Common\ConfirmDialogWidget.h` - Reused as-is: understand API (SetMessage, SetButtonLabels, ShowPopup, ClosePopup, OnConfirmed, OnCancelled)
- `C:\UEProjects\WjWorld\Source\WjWorld\UI\WaitingRoom\WaitingRoomHUDWidget.cpp` - Reference pattern: `OnLeaveClicked()` at lines 178-204 for the LeaveRoom + OpenLevel flow
- `C:\UEProjects\WjWorld\Source\WjWorld\Core\WjWorldGameInstance.cpp` - Reference: `LeaveRoom()` calls `SessionManager->DestroySession()`, handles both host and client

